/**
 * The Call
 * ----------
 * The Lord touches the prophet's mouth and says: I have put my words in your mouth, to pluck up and to break down, to build and to plant. Stage: a young man at a village gate at dawn, a hand of light at his mouth, a branch of an almond tree nearby; a thin morning, a heavy commission.
 *
 * Palette 0x1a2a1a → 0x060402 · light: dawn · hero: gate
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./jeremiah-kit.js.
 */

import { THREE, createScene, cityGate, house, oak, person, birds } from './jeremiah-kit.js';

const BG = 0x1a2a1a;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 878014320, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — dawn */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-58, 30, -145], 9, 0xffd9a0);
    W.disc([-58, 30, -155], 16, 0xffb060, 0.22);
    W.stars(60, 150, [0xcfd8e8, 0xbfd0e0], 0.55);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-60, 34, -120, 24], [10, 40, -135, 30], [70, 33, -125, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xd8c8b8, { opacity: 0.5 }), [x, y, z], { s: [s, s * 0.24, s * 0.5] });
    });
    W.backdrop(clouds);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* city: gate, towers and houses on the far side */
    const city = W.grp(group, [14, 0, -58], { name: 'city', r: [0, 0.10, 0] });
    cityGate(W, city, 0, 0, 0, 1.15, { stone: 0x060402, trim: 0x050302 });
    for (let i = 0; i < 5; i++) {
        house(W, city, -34 + i * 17 + W.rr(-4, 4), 0, W.rr(-14, 6), 0.85 + W.r() * 0.4, { mud: 0x060402 });
    }
    W.backdrop(city);

    /* trees: broadleaf shade */
    oak(W, group, 76.4, 0, -17.1, 1.36, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, 2.1, 0, -55.8, 1.10, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, -57.2, 0, 0.8, 1.36, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, 57.1, 0, -39.6, 1.34, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, -15.2, 0, -59.5, 1.26, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });

    /* hero: the gate */
    cityGate(W, group, 0, 0, -6, 1.0, { stone: 0x060402, trim: 0x050302 });

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x8a6a44, head: 'wrap', wrap: 0x1e301e, wrapTrim: 0x121d12, beard: 'long', ry: 0.52, s: 1.14 });
    person(W, group, [4.5, 0, 6], { robe: 0x8a6a44, head: 'wrap', wrap: 0x1e301e, wrapTrim: 0x121d12, beard: 'long', ry: 0.24, s: 1.17 });
    person(W, group, [1, 0, -5], { robe: 0x8a6a44, head: 'wrap', wrap: 0x1e301e, wrapTrim: 0x121d12, beard: 'long', ry: -0.31, s: 1.14 });

    /* birds: slow circles high above */
    birds(W, group, 8, 55, { y: 26 });

    return W.finish();
}

export default { build };
